std::optional<std::vector<TrajectoryPoint>> MPTOptimizer::optimizeTrajectory(
  const PlannerData & planner_data)
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);

  const auto & p = planner_data;
  const auto & traj_points = p.traj_points;

  // 1. calculate reference points
  auto [ref_points, ref_points_spline] = calcReferencePoints(planner_data, traj_points);
  if (ref_points.size() < 2) {
    RCLCPP_INFO_EXPRESSION(
      logger_, enable_debug_info_, "return std::nullopt since ref_points size is less than 2.");
    return std::nullopt;
  }

  // 2. calculate B and W matrices where x = B u + W
  const auto mpt_mat = state_equation_generator_.calcMatrix(ref_points);

  // 3. calculate Q and R matrices where J(x, u) = x^t Q x + u^t R u
  const auto val_mat = calcValueMatrix(ref_points, traj_points);

  // 4. get objective matrix
  const auto obj_mat = calcObjectiveMatrix(mpt_mat, val_mat, ref_points);

  // 5. get constraints matrix
  const auto const_mat = calcConstraintMatrix(mpt_mat, ref_points);

  // 6. optimize steer angles
  const auto optimized_variables = calcOptimizedSteerAngles(ref_points, obj_mat, const_mat);
  if (!optimized_variables && !mpt_param_.use_acados) {
    RCLCPP_WARN(logger_, "return std::nullopt since could not solve qp");

    return std::nullopt;
  }

  // 7. convert to points with validation
  std::optional<std::vector<TrajectoryPoint>> mpt_traj_points =
    optimized_variables ? calcMPTPoints(ref_points, *optimized_variables, mpt_mat) : std::nullopt;
  if (!mpt_traj_points && !mpt_param_.use_acados) {
    RCLCPP_WARN(logger_, "return std::nullopt since lateral or yaw error is too large.");
    return std::nullopt;
  }

  std::optional<std::vector<TrajectoryPoint>> output_trajectory = mpt_traj_points;

  if (mpt_param_.use_acados) {
    ref_points_spline.updateCurvatureSpline();

    if (optimized_variables) {
      const size_t D_x = state_equation_generator_.getDimX();
      const size_t D_u = state_equation_generator_.getDimU();
      const size_t N_ref = ref_points.size();
      const size_t N_x = N_ref * D_x;
      const size_t N_u = (N_ref - 1) * D_u;
      const auto & optimized_states = optimized_variables->segment(0, N_x);
      const auto & optimized_steering = optimized_variables->segment(N_x, N_u);
      publishOptimizedSteering(optimized_steering);
      publishOptimizedStates(optimized_states, N_ref);
    }

    // 8. run acados mpt (optional)
    std::optional<std::vector<TrajectoryPoint>> acados_traj_points;
    AcadosSolution acados_result;

    time_keeper_->start_track("runAcadosMPT");
    acados_result = runAcadosMPT(ref_points, ref_points_spline, p.ego_pose);
    time_keeper_->end_track("runAcadosMPT");

    acados_traj_points = convertAcadosSolutionToTrajectory(ref_points, acados_result);

    if (!acados_traj_points) {
      RCLCPP_WARN(logger_, "Failed to convert Acados solution to trajectory");
      return std::nullopt;
    }

    updateDebugDataAndPublishAcadosSteering(acados_result, ref_points, *acados_traj_points);

    // 9.b. publish acados trajectory for debug
    publishAcadosTrajectory(*acados_traj_points, p.header);

    publishAcadosStates(acados_result);

    publishReferenceTrajectory(ref_points, p.header);

    publishReferenceSteeringAngles(ref_points_spline);

    output_trajectory = std::move(acados_traj_points);
  }

  if (mpt_traj_points) {
    // 9.a. publish trajectories for debug
    publishDebugTrajectories(p.header, ref_points, *mpt_traj_points);
  } else {
    publishDebugTrajectories(p.header, ref_points, std::vector<TrajectoryPoint>());
  }

  debug_data_ptr_->ref_points = ref_points;
  prev_ref_points_ptr_ = std::make_shared<std::vector<ReferencePoint>>(ref_points);
  prev_optimized_traj_points_ptr_ =
    mpt_traj_points ? std::make_shared<std::vector<TrajectoryPoint>>(std::move(*mpt_traj_points))
                    : nullptr;

  return output_trajectory;
}

MPTOptimizer::calcReferencePoints(
  const PlannerData & planner_data, const std::vector<TrajectoryPoint> & smoothed_points)
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);

  const auto & p = planner_data;

  const double forward_traj_length = mpt_param_.num_points * mpt_param_.delta_arc_length;
  const double backward_traj_length = traj_param_.output_backward_traj_length;

  // 1. resample and convert smoothed points type from trajectory points to reference points
  time_keeper_->start_track("resampleReferencePoints");
  std::vector<ReferencePoint> ref_points = [&]() {
    const auto resampled_smoothed_points =
      trajectory_utils::resampleTrajectoryPointsWithoutStopPoint(
        smoothed_points, mpt_param_.delta_arc_length);
    return trajectory_utils::convertToReferencePoints(resampled_smoothed_points);
  }();
  time_keeper_->end_track("resampleReferencePoints");

  // 2. crop forward and backward with margin, and calculate spline interpolation
  // NOTE: Margin is added to calculate orientation, curvature, etc precisely.
  //       Start point may change. Spline calculation is required.
  constexpr double tmp_margin = 10.0;
  size_t ego_seg_idx =
    trajectory_utils::findEgoSegmentIndex(ref_points, p.ego_pose, ego_nearest_param_);
  ref_points = autoware::motion_utils::cropPoints(
    ref_points, p.ego_pose.position, ego_seg_idx, forward_traj_length + tmp_margin,
    backward_traj_length + tmp_margin);

  // remove repeated points
  ref_points = trajectory_utils::sanitizePoints(ref_points);
  autoware::interpolation::SplineInterpolationPoints2d ref_points_spline(ref_points);
  ego_seg_idx = trajectory_utils::findEgoSegmentIndex(ref_points, p.ego_pose, ego_nearest_param_);

  // 3. calculate orientation and curvature
  updateOrientation(ref_points, ref_points_spline);
  updateCurvature(ref_points, ref_points_spline);

  // 4. crop backward
  // NOTE: Start point may change; spline is refreshed after updateFixedPoint (step 5).
  ref_points = autoware::motion_utils::cropPoints(
    ref_points, p.ego_pose.position, ego_seg_idx, forward_traj_length + tmp_margin,
    backward_traj_length);
  ego_seg_idx = trajectory_utils::findEgoSegmentIndex(ref_points, p.ego_pose, ego_nearest_param_);

  // 5. update fixed points, and resample
  // NOTE: This must be after backward cropping.
  //       New start point may be added and resampled. Spline is rebuilt on ref_points below.
  updateFixedPoint(ref_points);
  ref_points = trajectory_utils::sanitizePoints(ref_points);
  ref_points_spline = autoware::interpolation::SplineInterpolationPoints2d(ref_points);

  // 6. update bounds
  // NOTE: After this, resample must not be called since bounds are not interpolated.
  updateBounds(ref_points, p.left_bound, p.right_bound, p.ego_pose, p.ego_vel);
  updateVehicleBounds(ref_points, ref_points_spline);

  // 7. update delta arc length
  updateDeltaArcLength(ref_points);

  // 8. update extra information (alpha and beta)
  // NOTE: This must be after calculation of bounds and delta arc length
  updateExtraPoints(ref_points);

  // 9. crop forward — pre-acados used resize(); acados path uses cropForwardPoints
  if (mpt_param_.use_acados) {
    ego_seg_idx = trajectory_utils::findEgoSegmentIndex(ref_points, p.ego_pose, ego_nearest_param_);
    ref_points = autoware::motion_utils::cropForwardPoints(
      ref_points, p.ego_pose.position, ego_seg_idx, forward_traj_length);

    if (ref_points.size() < 2) {
      return std::make_pair(ref_points, autoware::interpolation::SplineInterpolationPoints2d{});
    }

    // Must rebuild spline after forward crop; returning the pre-crop spline breaks
    // projectPointOntoSpline / yaw / curvature when ego or the window jumps.
    ref_points_spline = autoware::interpolation::SplineInterpolationPoints2d(ref_points);
    updateOrientation(ref_points, ref_points_spline);
    updateCurvature(ref_points, ref_points_spline);

    return std::make_pair(ref_points, ref_points_spline);
  }

  if (static_cast<size_t>(mpt_param_.num_points) < ref_points.size()) {
    ref_points.resize(mpt_param_.num_points);
  }

  ref_points_spline = autoware::interpolation::SplineInterpolationPoints2d(ref_points);
  return std::make_pair(ref_points, ref_points_spline);
}

std::vector<TrajectoryPoint> resampleTrajectoryPointsWithoutStopPoint(
  const std::vector<TrajectoryPoint> & traj_points, const double interval)
{
  constexpr bool enable_resampling_stop_point = false;

  const auto traj = autoware::motion_utils::convertToTrajectory(traj_points);
  const auto resampled_traj = autoware::motion_utils::resampleTrajectory(
    traj, interval, false, true, true, enable_resampling_stop_point);
  return autoware::motion_utils::convertToTrajectoryPointArray(resampled_traj);
}

autoware_planning_msgs::msg::Trajectory convertToTrajectory(
  const std::vector<autoware_planning_msgs::msg::TrajectoryPoint> & trajectory,
  const std_msgs::msg::Header & header)
{
  autoware_planning_msgs::msg::Trajectory output{};
  output.header = header;
  for (const auto & pt : trajectory) output.points.push_back(pt);
  return output;
}

autoware_planning_msgs::msg::Trajectory resampleTrajectory(
  const autoware_planning_msgs::msg::Trajectory & input_trajectory, const double resample_interval,
  const bool use_akima_spline_for_xy, const bool use_lerp_for_z,
  const bool use_zero_order_hold_for_twist, const bool resample_input_trajectory_stop_point)
{
  // validate arguments
  if (!resample_utils::validate_arguments(input_trajectory.points, resample_interval)) {
    return input_trajectory;
  }

  const double input_trajectory_len =
    autoware::motion_utils::calcArcLength(input_trajectory.points);

  std::vector<double> resampling_arclength;
  for (double s = 0.0; s < input_trajectory_len; s += resample_interval) {
    resampling_arclength.push_back(s);
  }
  if (resampling_arclength.empty()) {
    std::cerr << "[autoware_motion_utils]: resampling arclength is empty" << std::endl;
    return input_trajectory;
  }

  // Insert terminal point
  if (
    input_trajectory_len - resampling_arclength.back() <
    autoware::motion_utils::overlap_threshold) {
    resampling_arclength.back() = input_trajectory_len;
  } else {
    resampling_arclength.push_back(input_trajectory_len);
  }

  // Insert stop point
  if (resample_input_trajectory_stop_point) {
    const auto distance_to_stop_point =
      autoware::motion_utils::calcDistanceToForwardStopPoint(input_trajectory.points, 0);
    if (distance_to_stop_point && !resampling_arclength.empty()) {
      const double stop_dist = *distance_to_stop_point;
      for (size_t i = 1; i < resampling_arclength.size(); ++i) {
        if (resampling_arclength.at(i - 1) <= stop_dist && stop_dist < resampling_arclength.at(i)) {
          const double dist_to_prev_point = std::fabs(stop_dist - resampling_arclength.at(i - 1));
          const double dist_to_following_point = std::fabs(resampling_arclength.at(i) - stop_dist);
          if (dist_to_prev_point < autoware::motion_utils::overlap_threshold) {
            resampling_arclength.at(i - 1) = stop_dist;
          } else if (dist_to_following_point < autoware::motion_utils::overlap_threshold) {
            resampling_arclength.at(i) = stop_dist;
          } else {
            resampling_arclength.insert(
              resampling_arclength.begin() + static_cast<std::ptrdiff_t>(i), stop_dist);
          }
          break;
        }
      }
    }
  }

  return resampleTrajectory(
    input_trajectory, resampling_arclength, use_akima_spline_for_xy, use_lerp_for_z,
    use_zero_order_hold_for_twist);
}

[[nodiscard]] bool validate_arguments(
  const T & input_points, const std::vector<double> & resampling_intervals)
{
  // Check size of the arguments
  if (!validate_size(input_points)) {
    RCLCPP_DEBUG(get_logger(), "invalid argument: The number of input points is less than 2");
    autoware_utils_system::print_backtrace();
    return false;
  }
  if (!validate_size(resampling_intervals)) {
    RCLCPP_DEBUG(
      get_logger(), "invalid argument: The number of resampling intervals is less than 2");
    autoware_utils_system::print_backtrace();
    return false;
  }

  // Check resampling range
  if (!validate_resampling_range(input_points, resampling_intervals)) {
    RCLCPP_DEBUG(get_logger(), "invalid argument: resampling interval is longer than input points");
    autoware_utils_system::print_backtrace();
    return false;
  }

  // Check duplication
  if (!validate_points_duplication(input_points)) {
    RCLCPP_DEBUG(get_logger(), "invalid argument: input points has some duplicated points");
    autoware_utils_system::print_backtrace();
    return false;
  }

  return true;
}

[[nodiscard]] bool validate_size(const T & points)
{
  return points.size() >= 2;
}

[[nodiscard]] bool validate_resampling_range(
  const T & points, const std::vector<double> & resampling_intervals)
{
  const double points_length = autoware::motion_utils::calcArcLength(points);
  return points_length >= resampling_intervals.back();
}

[[nodiscard]] double calcArcLength(const T & points)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  return calcSignedArcLength(points, 0, points.size() - 1);
}

double calcSignedArcLength(const T & points, const size_t src_idx, const size_t dst_idx)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  if (src_idx > dst_idx) {
    return -calcSignedArcLength(points, dst_idx, src_idx);
  }

  double dist_sum = 0.0;
  for (size_t i = src_idx; i < dst_idx; ++i) {
    dist_sum += autoware_utils_geometry::calc_distance2d(points.at(i), points.at(i + 1));
  }
  return dist_sum;
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
