std::vector<double> SplineInterpolationPoints2d::getSplineInterpolatedYaws() const
{
  std::vector<double> yaw_vec;
  for (size_t i = 0; i < spline_x_.getSize(); ++i) {
    const double yaw = getSplineInterpolatedYaw(i, 0.0);
    yaw_vec.push_back(yaw);
  }
  return yaw_vec;
}

double SplineInterpolationPoints2d::getSplineInterpolatedYaw(const size_t idx, const double s) const
{
  if (base_s_vec_.size() <= idx) {
    throw std::out_of_range("idx is out of range.");
  }

  const double whole_s =
    std::clamp(base_s_vec_.at(idx) + s, base_s_vec_.front(), base_s_vec_.back());

  const double diff_x = spline_x_.getSplineInterpolatedDiffValues({whole_s}).at(0);
  const double diff_y = spline_y_.getSplineInterpolatedDiffValues({whole_s}).at(0);

  return std::atan2(diff_y, diff_x);
}

std::vector<double> SplineInterpolation::getSplineInterpolatedDiffValues(
  const std::vector<double> & query_keys) const
{
  // throw exceptions for invalid arguments
  const auto validated_query_keys = autoware::interpolation::validateKeys(base_keys_, query_keys);
  std::vector<double> interpolated_diff_values;
  interpolated_diff_values.reserve(query_keys.size());

  for (const auto & key : query_keys) {
    const auto idx = get_index(key);
    const auto dx = key - base_keys_[idx];
    interpolated_diff_values.emplace_back(3 * a_[idx] * dx * dx + 2 * b_[idx] * dx + c_[idx]);
  }

  return interpolated_diff_values;
}

inline std::vector<double> validateKeys(
  const std::vector<double> & base_keys, const std::vector<double> & query_keys)
{
  // when vectors are empty
  if (base_keys.empty() || query_keys.empty()) {
    throw std::invalid_argument("Points is empty.");
  }

  // when size of vectors are less than 2
  if (base_keys.size() < 2) {
    throw std::invalid_argument(
      "The size of points is less than 2. base_keys.size() = " + std::to_string(base_keys.size()));
  }

  // when indices are not sorted
  if (!isIncreasing(base_keys) || !isNotDecreasing(query_keys)) {
    throw std::invalid_argument("Either base_keys or query_keys is not sorted.");
  }

  // when query_keys is out of base_keys (This function does not allow exterior division.)
  constexpr double epsilon = 1e-3;
  if (
    query_keys.front() < base_keys.front() - epsilon ||
    base_keys.back() + epsilon < query_keys.back()) {
    throw std::invalid_argument("query_keys is out of base_keys");
  }

  // NOTE: Due to calculation error of double, a query key may be slightly out of base keys.
  //       Therefore, query keys are cropped here.
  auto validated_query_keys = query_keys;
  validated_query_keys.front() = std::max(validated_query_keys.front(), base_keys.front());
  validated_query_keys.back() = std::min(validated_query_keys.back(), base_keys.back());

  return validated_query_keys;
}

inline bool isIncreasing(const std::vector<double> & x)
{
  if (x.empty()) {
    throw std::invalid_argument("Points is empty.");
  }

  for (size_t i = 0; i < x.size() - 1; ++i) {
    if (x.at(i) >= x.at(i + 1)) {
      return false;
    }
  }

  return true;
}

inline bool isNotDecreasing(const std::vector<double> & x)
{
  if (x.empty()) {
    throw std::invalid_argument("Points is empty.");
  }

  for (size_t i = 0; i < x.size() - 1; ++i) {
    if (x.at(i) > x.at(i + 1)) {
      return false;
    }
  }

  return true;
}

Eigen::Index SplineInterpolation::get_index(const double & key) const
{
  const auto it = std::lower_bound(base_keys_.begin(), base_keys_.end(), key);
  return std::clamp(
    static_cast<int>(std::distance(base_keys_.begin(), it)) - 1, 0,
    static_cast<int>(base_keys_.size()) - 2);
}

geometry_msgs::msg::Quaternion create_quaternion_from_yaw(const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(0, 0, yaw);
  return tf2::toMsg(q);
}

void MPTOptimizer::updateBounds(
  std::vector<ReferencePoint> & ref_points,
  const std::vector<geometry_msgs::msg::Point> & left_bound,
  const std::vector<geometry_msgs::msg::Point> & right_bound,
  const geometry_msgs::msg::Pose & ego_pose, const double ego_vel) const
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);

  const double soft_road_clearance =
    mpt_param_.soft_clearance_from_road + vehicle_info_.vehicle_width_m / 2.0;

  // calculate distance to left/right bound on each reference point
  // NOTE: Reference points is sometimes not fully covered by the drivable area.
  //       In some edge cases like U-turn, the wrong bound may be found. To avoid finding the wrong
  //       bound, some beginning bounds are copied from the following one.
  const size_t min_ref_point_index = std::min(
    static_cast<size_t>(std::ceil(1.0 / mpt_param_.delta_arc_length)), ref_points.size() - 1);
  for (size_t i = 0; i < ref_points.size(); ++i) {
    const auto ref_point_for_bound_search = ref_points.at(std::max(min_ref_point_index, i));
    const double dist_to_left_bound = calcLateralDistToBounds(
      ref_point_for_bound_search.pose, left_bound, soft_road_clearance, true);
    const double dist_to_right_bound = calcLateralDistToBounds(
      ref_point_for_bound_search.pose, right_bound, soft_road_clearance, false);
    ref_points.at(i).bounds = Bounds{dist_to_right_bound, dist_to_left_bound};
  }

  // keep vehicle width + margin
  // NOTE: The drivable area's width is sometimes narrower than the vehicle width which means
  // infeasible to run especially when obstacles are extracted from the drivable area.
  //       In this case, the drivable area's width is forced to be wider.
  keepMinimumBoundsWidth(ref_points);

  // extend violated bounds, where the input path is outside the drivable area
  ref_points = extendViolatedBounds(ref_points);

  // keep previous boundary's width around ego to avoid sudden steering
  avoidSuddenSteering(ref_points, ego_pose, ego_vel);

  /*
  // TODO(murooka) deal with filling data between obstacles
  // fill between obstacles
  constexpr double max_longitudinal_length_to_fill_drivable_area = 20;
  const int edge_fill_index = std::ceil(max_longitudinal_length_to_fill_drivable_area /
  mpt_param_.delta_arc_length / 2); for (int i = 0; i < ref_points.size(); ++i) { for (int j =
  -edge_fill_index; j <= edge_fill_index; ++j) { const int k = i + j; if (k < 0 || ref_points.size()
  - 1 <= k) { continue;
      }

      const auto normalized_avoidance_cost = calcNormalizedAvoidanceCost(ref_points.at(k));
      if (normalized_avoidance_cost) {
      }
    }
  }
  */
  return;
}

double calcLateralDistToBounds(
  const geometry_msgs::msg::Pose & pose, const std::vector<geometry_msgs::msg::Point> & bound,
  const double additional_offset, const bool is_left_bound = true)
{
  constexpr double max_lat_offset_for_left = 5.0;
  constexpr double min_lat_offset_for_left = -5.0;

  const double max_lat_offset = is_left_bound ? max_lat_offset_for_left : -max_lat_offset_for_left;
  const double min_lat_offset = is_left_bound ? min_lat_offset_for_left : -min_lat_offset_for_left;
  const auto max_lat_offset_point =
    autoware_utils::calc_offset_pose(pose, 0.0, max_lat_offset, 0.0).position;
  const auto min_lat_offset_point =
    autoware_utils::calc_offset_pose(pose, 0.0, min_lat_offset, 0.0).position;

  double closest_dist_to_bound = max_lat_offset;
  for (size_t i = 0; i < bound.size() - 1; ++i) {
    const auto intersect_point = autoware_utils::intersect(
      min_lat_offset_point, max_lat_offset_point, bound.at(i), bound.at(i + 1));
    if (intersect_point) {
      const bool is_point_left = isLeft(pose, *intersect_point);
      const double dist_to_bound =
        autoware_utils::calc_distance2d(pose.position, *intersect_point) *
        (is_point_left ? 1.0 : -1.0);

      // the bound which is closest to the centerline will be chosen
      const double tmp_dist_to_bound =
        is_left_bound ? dist_to_bound - additional_offset : dist_to_bound + additional_offset;
      if (std::abs(tmp_dist_to_bound) < std::abs(closest_dist_to_bound)) {
        closest_dist_to_bound = tmp_dist_to_bound;
      }
    }
  }

  return closest_dist_to_bound;
}

geometry_msgs::msg::Pose calc_offset_pose(
  const geometry_msgs::msg::Pose & p, const double x, const double y, const double z,
  const double yaw)
{
  geometry_msgs::msg::Pose pose;
  geometry_msgs::msg::Transform transform;
  transform.translation = create_translation(x, y, z);
  transform.rotation = create_quaternion_from_yaw(yaw);
  tf2::Transform tf_pose;
  tf2::Transform tf_offset;
  tf2::fromMsg(transform, tf_offset);
  tf2::fromMsg(p, tf_pose);
  tf2::toMsg(tf_pose * tf_offset, pose);
  return pose;
}

geometry_msgs::msg::Vector3 create_translation(const double x, const double y, const double z)
{
  geometry_msgs::msg::Vector3 v;
  v.x = x;
  v.y = y;
  v.z = z;
  return v;
}

geometry_msgs::msg::Quaternion create_quaternion_from_yaw(const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(0, 0, yaw);
  return tf2::toMsg(q);
}

std::optional<geometry_msgs::msg::Point> intersect(
  const geometry_msgs::msg::Point & p1, const geometry_msgs::msg::Point & p2,
  const geometry_msgs::msg::Point & p3, const geometry_msgs::msg::Point & p4)
{
  // Compute the determinant to check if the two lines are parallel.
  // If det is close to zero, the lines are nearly parallel and there's
  // no unique intersection point.
  const double det = (p1.x - p2.x) * (p4.y - p3.y) - (p4.x - p3.x) * (p1.y - p2.y);

  // A small tolerance factor for geometric computations.
  // Used to make the intersection detection more robust against
  // floating-point precision errors and to handle borderline cases consistently.
  constexpr double geometric_epsilon = 1e-9;

  if (std::abs(det) < geometric_epsilon) {
    // Lines are nearly parallel — treat this as no single intersection point.
    return std::nullopt;
  }

  const double t = ((p4.y - p3.y) * (p4.x - p2.x) + (p3.x - p4.x) * (p4.y - p2.y)) / det;
  const double s = ((p2.y - p1.y) * (p4.x - p2.x) + (p1.x - p2.x) * (p4.y - p2.y)) / det;

  // Helper function to check whether the intersection parameter is slightly
  // outside the [0, 1] range, considering a small tolerance margin.
  const auto is_outside_interval = [&](const double t) {
    return t < -geometric_epsilon || (1.0 + geometric_epsilon) < t;
  };

  // check collision is outside the segment line
  // Check if the computed intersection lies outside the segment boundaries.
  // The tolerance helps to avoid jitter or inconsistent results for
  // near-boundary cases caused by floating-point errors.
  if (is_outside_interval(t) || is_outside_interval(s)) {
    return std::nullopt;
  }

  geometry_msgs::msg::Point intersect_point;
  intersect_point.x = t * p1.x + (1.0 - t) * p2.x;
  intersect_point.y = t * p1.y + (1.0 - t) * p2.y;
  intersect_point.z = t * p1.z + (1.0 - t) * p2.z;
  return intersect_point;
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

