bool isFrontDrivableArea(
  const geometry_msgs::msg::Point & point,
  const std::vector<geometry_msgs::msg::Point> & left_bound,
  const std::vector<geometry_msgs::msg::Point> & right_bound)
{
  if (left_bound.size() < 2 || right_bound.size() < 2) {
    return false;
  }

  constexpr double min_dist = 0.1;
  const auto left_start_point = getStartPoint(left_bound, right_bound.front());
  const auto right_start_point = getStartPoint(right_bound, left_bound.front());

  // ignore point behind of the front line
  const std::vector<geometry_msgs::msg::Point> front_bound = {left_start_point, right_start_point};
  const double lat_dist_to_front_bound =
    autoware::motion_utils::calcLateralOffset(front_bound, point);
  if (lat_dist_to_front_bound < min_dist) {
    return true;
  }

  return false;
}

geometry_msgs::msg::Point getStartPoint(
  const std::vector<geometry_msgs::msg::Point> & bound, const geometry_msgs::msg::Point & point)
{
  const size_t segment_idx = autoware::motion_utils::findNearestSegmentIndex(bound, point);
  const auto & curr_seg_point = bound.at(segment_idx);
  const auto & next_seg_point = bound.at(segment_idx + 1);
  const Eigen::Vector2d first_to_target{point.x - curr_seg_point.x, point.y - curr_seg_point.y};
  const Eigen::Vector2d first_to_second{
    next_seg_point.x - curr_seg_point.x, next_seg_point.y - curr_seg_point.y};
  const double length = first_to_target.dot(first_to_second.normalized());

  if (length < 0.0) {
    return bound.front();
  }

  const auto first_point =
    autoware::motion_utils::calcLongitudinalOffsetPoint(bound, segment_idx, length);
  if (first_point) {
    return *first_point;
  }

  return bound.front();
}

size_t findNearestSegmentIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  const size_t nearest_idx = findNearestIndex(points, point);

  if (nearest_idx == 0) {
    return 0;
  }
  if (nearest_idx == points.size() - 1) {
    return points.size() - 2;
  }

  const double signed_length = calcLongitudinalOffsetToSegment(points, nearest_idx, point);

  if (signed_length <= 0) {
    return nearest_idx - 1;
  }

  return nearest_idx;
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

