Polygon2d createDrivablePolygon(
  const std::vector<geometry_msgs::msg::Point> & left_bound,
  const std::vector<geometry_msgs::msg::Point> & right_bound)
{
  Polygon2d drivable_area_poly;

  // left bound
  for (const auto & p : left_bound) {
    drivable_area_poly.outer().emplace_back(p.x, p.y);
  }

  // right bound
  auto reversed_right_bound = right_bound;
  std::reverse(reversed_right_bound.begin(), reversed_right_bound.end());
  for (const auto & p : reversed_right_bound) {
    drivable_area_poly.outer().emplace_back(p.x, p.y);
  }

  drivable_area_poly.outer().push_back(drivable_area_poly.outer().front());
  return drivable_area_poly;
}

std::optional<size_t> insertTargetPoint(
  const size_t src_segment_idx, const double insert_point_length, T & points,
  const double overlap_threshold = 1e-3)
{
  validateNonEmpty(points);

  if (src_segment_idx >= points.size() - 1) {
    return std::nullopt;
  }

  // Get Nearest segment index
  std::optional<size_t> segment_idx = std::nullopt;
  if (0.0 <= insert_point_length) {
    for (size_t i = src_segment_idx + 1; i < points.size(); ++i) {
      const double length = calcSignedArcLength(points, src_segment_idx, i);
      if (insert_point_length <= length) {
        segment_idx = i - 1;
        break;
      }
    }
  } else {
    for (int i = src_segment_idx - 1; 0 <= i; --i) {
      const double length = calcSignedArcLength(points, src_segment_idx, i);
      if (length <= insert_point_length) {
        segment_idx = i;
        break;
      }
    }
  }

  if (!segment_idx) {
    return std::nullopt;
  }

  // Get Target Point
  const double segment_length = calcSignedArcLength(points, *segment_idx, *segment_idx + 1);
  const double target_length =
    insert_point_length - calcSignedArcLength(points, src_segment_idx, *segment_idx);
  const double ratio = std::clamp(target_length / segment_length, 0.0, 1.0);
  const auto p_target = autoware_utils_geometry::calc_interpolated_point(
    autoware_utils_geometry::get_point(points.at(*segment_idx)),
    autoware_utils_geometry::get_point(points.at(*segment_idx + 1)), ratio);

  return insertTargetPoint(*segment_idx, p_target, points, overlap_threshold);
}

double calcSignedArcLength(const T & points, const size_t src_idx, const size_t dst_idx)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  if (src_idx > dst_idx) {
    return -calcSignedArcLength(points, dst_idx, src_idx);
  }

  double dist_sum = 0.0;
  for (size_t i = src_idx; i < dst_idx; ++i) {
    dist_sum += autoware_utils_geometry::calc_distance2d(points.at(i), points.at(i + 1));
  }
  return dist_sum;
}

double calcSignedArcLength(const T & points, const size_t src_idx, const size_t dst_idx)
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return 0.0;
  }

  if (src_idx > dst_idx) {
    return -calcSignedArcLength(points, dst_idx, src_idx);
  }

  double dist_sum = 0.0;
  for (size_t i = src_idx; i < dst_idx; ++i) {
    dist_sum += autoware_utils_geometry::calc_distance2d(points.at(i), points.at(i + 1));
  }
  return dist_sum;
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

