double lerp(const double src_val, const double dst_val, const double ratio)
{
  return src_val + (dst_val - src_val) * ratio;
}

std::vector<double> splineByAkima(
  const std::vector<double> & base_keys, const std::vector<double> & base_values,
  const std::vector<double> & query_keys)
{
  constexpr double epsilon = 1e-5;

  // calculate m
  std::vector<double> m_values;
  for (size_t i = 0; i < base_keys.size() - 1; ++i) {
    const double m_val =
      (base_values.at(i + 1) - base_values.at(i)) / (base_keys.at(i + 1) - base_keys.at(i));
    m_values.push_back(m_val);
  }

  // calculate s
  std::vector<double> s_values;
  for (size_t i = 0; i < base_keys.size(); ++i) {
    if (i == 0) {
      s_values.push_back(m_values.front());
      continue;
    } else if (i == base_keys.size() - 1) {
      s_values.push_back(m_values.back());
      continue;
    } else if (i == 1 || i == base_keys.size() - 2) {
      const double s_val = (m_values.at(i - 1) + m_values.at(i)) / 2.0;
      s_values.push_back(s_val);
      continue;
    }

    const double denom = std::abs(m_values.at(i + 1) - m_values.at(i)) +
                         std::abs(m_values.at(i - 1) - m_values.at(i - 2));
    if (std::abs(denom) < epsilon) {
      const double s_val = (m_values.at(i - 1) + m_values.at(i)) / 2.0;
      s_values.push_back(s_val);
      continue;
    }

    const double s_val = (std::abs(m_values.at(i + 1) - m_values.at(i)) * m_values.at(i - 1) +
                          std::abs(m_values.at(i - 1) - m_values.at(i - 2)) * m_values.at(i)) /
                         denom;
    s_values.push_back(s_val);
  }

  // calculate cubic coefficients
  std::vector<double> a;
  std::vector<double> b;
  std::vector<double> c;
  std::vector<double> d;
  for (size_t i = 0; i < base_keys.size() - 1; ++i) {
    a.push_back(
      (s_values.at(i) + s_values.at(i + 1) - 2.0 * m_values.at(i)) /
      std::pow(base_keys.at(i + 1) - base_keys.at(i), 2));
    b.push_back(
      (3.0 * m_values.at(i) - 2.0 * s_values.at(i) - s_values.at(i + 1)) /
      (base_keys.at(i + 1) - base_keys.at(i)));
    c.push_back(s_values.at(i));
    d.push_back(base_values.at(i));
  }

  // interpolate
  std::vector<double> res;
  size_t j = 0;
  for (const auto & query_key : query_keys) {
    while (base_keys.at(j + 1) < query_key) {
      ++j;
    }

    const double ds = query_key - base_keys.at(j);
    res.push_back(d.at(j) + (c.at(j) + (b.at(j) + a.at(j) * ds) * ds) * ds);
  }
  return res;
}

bool is_driving_forward(const Pose1 & src_pose, const Pose2 & dst_pose)
{
  // check the first point direction
  const double src_yaw = tf2::getYaw(get_pose(src_pose).orientation);
  const double pose_direction_yaw = calc_azimuth_angle(get_point(src_pose), get_point(dst_pose));
  return std::fabs(normalize_radian(src_yaw - pose_direction_yaw)) < pi / 2.0;
}

double calc_azimuth_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dx = p_to.x - p_from.x;
  const double dy = p_to.y - p_from.y;
  return std::atan2(dy, dx);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

void insertOrientation(T & points, const bool is_driving_forward)
{
  if (is_driving_forward) {
    for (size_t i = 0; i < points.size() - 1; ++i) {
      const auto & src_point = autoware_utils_geometry::get_point(points.at(i));
      const auto & dst_point = autoware_utils_geometry::get_point(points.at(i + 1));
      // TODO(Yuki TAKAGI): The current implementation sets a value with the sign inverted. Fix in
      // https://github.com/autowarefoundation/autoware_core/issues/571
      const double pitch = autoware_utils_geometry::calc_elevation_angle(src_point, dst_point);
      const double yaw = autoware_utils_geometry::calc_azimuth_angle(src_point, dst_point);
      autoware_utils_geometry::set_orientation(
        autoware_utils_geometry::create_quaternion_from_rpy(0.0, pitch, yaw), points.at(i));
      if (i == points.size() - 2) {
        // Terminal orientation is same as the point before it
        autoware_utils_geometry::set_orientation(
          autoware_utils_geometry::get_pose(points.at(i)).orientation, points.at(i + 1));
      }
    }
  } else {
    for (size_t i = points.size() - 1; i >= 1; --i) {
      const auto & src_point = autoware_utils_geometry::get_point(points.at(i));
      const auto & dst_point = autoware_utils_geometry::get_point(points.at(i - 1));
      // NOTE: pitch sign is incorrect.
      const double pitch = autoware_utils_geometry::calc_elevation_angle(src_point, dst_point);
      const double yaw = autoware_utils_geometry::calc_azimuth_angle(src_point, dst_point);
      autoware_utils_geometry::set_orientation(
        autoware_utils_geometry::create_quaternion_from_rpy(0.0, pitch, yaw), points.at(i));
    }
    // Initial orientation is same as the point after it
    autoware_utils_geometry::set_orientation(
      autoware_utils_geometry::get_pose(points.at(1)).orientation, points.at(0));
  }
}

double calc_elevation_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dz = p_to.z - p_from.z;
  const double dist_2d = calc_distance2d(p_from, p_to);
  return std::atan2(dz, dist_2d);
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_azimuth_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dx = p_to.x - p_from.x;
  const double dy = p_to.y - p_from.y;
  return std::atan2(dy, dx);
}

